words_set = set()
clean_ch21 = []

for word, definition, example in raw_ocean_words:
    w = word.upper().strip().replace("-", "").replace(" ", "")
    if w in used_words:
        continue
    if w in words_set:
        continue
    if w.endswith('S') and w[:-1] in words_set:
        print(f"Skipping plural duplicate: {w} (base {w[:-1]} already present)")
        continue
    words_set.add(w)
    clean_ch21.append({
        "word": w,
        "definition": definition,
        "example": example
    })

print(f"Total raw words prepared: {len(raw_ocean_words)}")
print(f"Total valid unique Ch21 words: {len(clean_ch21)}")

assert len(clean_ch21) >= 364, f"Need at least 364 words, got {len(clean_ch21)}"

with open("scratch/chapter_21_clean_words.json", "w", encoding="utf-8") as f:
    json.dump(clean_ch21, f, indent=2)

